CREATE SCHEMA IF NOT EXISTS identity; CREATE SCHEMA IF NOT EXISTS taxpayer;
CREATE SCHEMA IF NOT EXISTS registration; CREATE SCHEMA IF NOT EXISTS filing;
CREATE SCHEMA IF NOT EXISTS assessment; CREATE SCHEMA IF NOT EXISTS payment;
CREATE SCHEMA IF NOT EXISTS ledger; CREATE SCHEMA IF NOT EXISTS document;
CREATE SCHEMA IF NOT EXISTS notification; CREATE SCHEMA IF NOT EXISTS administration;
CREATE SCHEMA IF NOT EXISTS audit; CREATE SCHEMA IF NOT EXISTS integration;

CREATE TABLE taxpayer.taxpayers (id uuid PRIMARY KEY, tenant_id text NOT NULL, jurisdiction_code text NOT NULL, legal_name text NOT NULL CHECK (length(legal_name) BETWEEN 1 AND 200), identifier_scheme text NOT NULL, identifier text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, jurisdiction_code, identifier_scheme, identifier));
CREATE TABLE registration.tax_registrations (id uuid PRIMARY KEY, tenant_id text NOT NULL, jurisdiction_code text NOT NULL, taxpayer_id uuid NOT NULL, tax_type_code text NOT NULL, status text NOT NULL CHECK (status IN ('SUBMITTED', 'APPROVED')), submitted_at timestamptz NOT NULL, approved_at timestamptz, approved_by text, CHECK ((status = 'SUBMITTED' AND approved_at IS NULL AND approved_by IS NULL) OR (status = 'APPROVED' AND approved_at IS NOT NULL AND approved_by IS NOT NULL)));
CREATE TABLE filing.tax_returns (id uuid PRIMARY KEY, tenant_id text NOT NULL, jurisdiction_code text NOT NULL, taxpayer_id uuid NOT NULL, registration_id uuid NOT NULL, period_id text NOT NULL, form_version text NOT NULL, rule_version text NOT NULL, status text NOT NULL CHECK (status IN ('DRAFT', 'VALIDATED', 'CALCULATED', 'SUBMITTED')), revision integer NOT NULL CHECK (revision > 0), original_return_id uuid NOT NULL, supersedes_id uuid, payload jsonb NOT NULL, payload_hash char(64), validation_result jsonb, calculation_result jsonb, frozen_payload_hash char(64), submitted_at timestamptz, UNIQUE (tenant_id, jurisdiction_code, original_return_id, revision), CHECK ((status = 'SUBMITTED' AND submitted_at IS NOT NULL AND frozen_payload_hash IS NOT NULL) OR status <> 'SUBMITTED'));
CREATE TABLE assessment.assessments (id uuid PRIMARY KEY, tenant_id text NOT NULL, jurisdiction_code text NOT NULL, taxpayer_id uuid NOT NULL, return_id uuid NOT NULL, amount_minor bigint NOT NULL CHECK (amount_minor >= 0), outstanding_minor bigint NOT NULL CHECK (outstanding_minor BETWEEN 0 AND amount_minor), currency char(3) NOT NULL, posting_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, jurisdiction_code, return_id));
CREATE TABLE payment.payments (id uuid PRIMARY KEY, tenant_id text NOT NULL, jurisdiction_code text NOT NULL, taxpayer_id uuid NOT NULL, amount_minor bigint NOT NULL CHECK (amount_minor > 0), allocated_minor bigint NOT NULL DEFAULT 0 CHECK (allocated_minor >= 0), unapplied_minor bigint NOT NULL CHECK (unapplied_minor >= 0), currency char(3) NOT NULL, status text NOT NULL CHECK (status IN ('UNAPPLIED', 'PARTIALLY_ALLOCATED', 'ALLOCATED')), version bigint NOT NULL DEFAULT 1 CHECK (version > 0), receipt_posting_id uuid NOT NULL, external_reference text, idempotency_key text, request_fingerprint char(64), created_at timestamptz NOT NULL DEFAULT now(), CHECK (allocated_minor + unapplied_minor = amount_minor), UNIQUE (tenant_id, jurisdiction_code, idempotency_key));
CREATE TABLE payment.allocations (id uuid PRIMARY KEY, tenant_id text NOT NULL, jurisdiction_code text NOT NULL, payment_id uuid NOT NULL REFERENCES payment.payments(id), assessment_id uuid NOT NULL REFERENCES assessment.assessments(id), amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency char(3) NOT NULL, payment_version bigint NOT NULL CHECK (payment_version > 1), posting_id uuid NOT NULL, allocated_at timestamptz NOT NULL, actor_id text NOT NULL, correlation_id text NOT NULL, causation_id text NOT NULL, UNIQUE (payment_id, payment_version));
CREATE TABLE ledger.postings (id uuid PRIMARY KEY, tenant_id text NOT NULL, jurisdiction_code text NOT NULL, reference_type text NOT NULL, reference_id text NOT NULL, posted_at timestamptz NOT NULL, reversal_of uuid REFERENCES ledger.postings(id), UNIQUE (tenant_id, jurisdiction_code, reference_type, reference_id));
CREATE TABLE ledger.entries (id uuid PRIMARY KEY, posting_id uuid NOT NULL REFERENCES ledger.postings(id), tenant_id text NOT NULL, jurisdiction_code text NOT NULL, taxpayer_id uuid NOT NULL, tax_registration_id uuid, tax_period_id text, account text NOT NULL CHECK (account IN ('TAXPAYER_RECEIVABLE', 'REVENUE_CONTROL', 'CASH_CONTROL', 'UNAPPLIED_CASH')), entry_type text NOT NULL, debit_minor bigint NOT NULL DEFAULT 0 CHECK (debit_minor >= 0), credit_minor bigint NOT NULL DEFAULT 0 CHECK (credit_minor >= 0), currency char(3) NOT NULL, reference_type text NOT NULL, reference_id text NOT NULL, effective_date date NOT NULL, posted_at timestamptz NOT NULL DEFAULT now(), reversal_of uuid REFERENCES ledger.entries(id), created_by text NOT NULL, correlation_id text NOT NULL, causation_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', CHECK ((debit_minor > 0) <> (credit_minor > 0)));
CREATE OR REPLACE FUNCTION ledger.reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'ledger entries are append-only'; END $$;
CREATE TRIGGER ledger_entries_immutable BEFORE UPDATE OR DELETE ON ledger.entries FOR EACH ROW EXECUTE FUNCTION ledger.reject_mutation();
CREATE TRIGGER ledger_postings_immutable BEFORE UPDATE OR DELETE ON ledger.postings FOR EACH ROW EXECUTE FUNCTION ledger.reject_mutation();
CREATE TRIGGER payment_allocations_immutable BEFORE UPDATE OR DELETE ON payment.allocations FOR EACH ROW EXECUTE FUNCTION ledger.reject_mutation();
CREATE OR REPLACE FUNCTION ledger.assert_posting_balanced() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE total_debits bigint; total_credits bigint; line_count integer; BEGIN SELECT COALESCE(sum(debit_minor), 0), COALESCE(sum(credit_minor), 0), count(*) INTO total_debits, total_credits, line_count FROM ledger.entries WHERE posting_id = NEW.posting_id; IF line_count < 2 OR total_debits <> total_credits OR total_debits <= 0 THEN RAISE EXCEPTION 'ledger posting % is not balanced', NEW.posting_id; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER ledger_posting_balanced AFTER INSERT ON ledger.entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ledger.assert_posting_balanced();
CREATE TABLE audit.events (id uuid PRIMARY KEY, tenant_id text NOT NULL, jurisdiction_code text NOT NULL, action text NOT NULL, actor text NOT NULL, actor_type text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, occurred_at timestamptz NOT NULL, correlation_id text NOT NULL, causation_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TRIGGER audit_events_immutable BEFORE UPDATE OR DELETE ON audit.events FOR EACH ROW EXECUTE FUNCTION ledger.reject_mutation();
CREATE TABLE integration.outbox (id uuid PRIMARY KEY, tenant_id text NOT NULL, jurisdiction_code text NOT NULL, actor_id text NOT NULL, actor_type text NOT NULL, correlation_id text NOT NULL, causation_id text NOT NULL, aggregate_type text NOT NULL, aggregate_id text NOT NULL, event_type text NOT NULL, event_version integer NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL, published_at timestamptz, attempts integer NOT NULL DEFAULT 0);
CREATE TABLE integration.idempotency_keys (tenant_id text NOT NULL, jurisdiction_code text NOT NULL, key text NOT NULL CHECK (length(key) BETWEEN 1 AND 128), operation text NOT NULL, request_fingerprint char(64) NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (tenant_id, jurisdiction_code, key, operation));
